CREATE TABLE ibexa_content_version (id SERIAL NOT NULL, contentobject_id INT DEFAULT NULL, created INT DEFAULT 0 NOT NULL, creator_id INT DEFAULT 0 NOT NULL, initial_language_id BIGINT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, modified INT DEFAULT 0 NOT NULL, status INT DEFAULT 0 NOT NULL, user_id INT DEFAULT 0 NOT NULL, version INT DEFAULT 0 NOT NULL, workflow_event_pos INT DEFAULT 0, PRIMARY KEY(id));
